$inline=str_starts_with($a['tipo_mime'],'image/')&&empty($_GET['download']);header('Content-Type: '.$a['tipo_mime']);header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');header('Content-Disposition: '.($inline?'inline':'attachment').'; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',$a['nome_arquivo']).'"');$key=$a['chave_arquivo'];
